insert into public.company_memory (id, cle, contenu) values
  ('mem_entreprise', 'entreprise', 'MJAGENCY — agence web & marketing digital pour commerçants et indépendants.'),
  ('mem_fondateurs', 'fondateurs', 'Jérémy Vatuone & Matheis Farrieux.'),
  ('mem_zone', 'zone', 'Sète, Frontignan, Balaruc, Bassin de Thau, Montpellier, Hérault.'),
  ('mem_coordonnees_legales', 'coordonnees_legales', '54 rue Marceau, 34200 Sète — SIRET 992 328 120 00017 — jeremyvatuonepro@gmail.com — 06 11 71 83 68 — TVA non applicable, art. 293 B du CGI.'),
  ('mem_boite_mail', 'boite_mail', 'Boîte mail officielle de l''agence (envois et réception) : mjagency.officiel@gmail.com'),
  ('mem_site', 'site', 'mjagency.eu'),
  ('mem_autre_activite', 'autre_activite', 'MJ E-comm (dropshipping Shopify), gérée à part de l''agence.'),
  ('mem_offres', 'offres', 'Sites web (grille actuelle 490 € à 1 900 €+, montée en gamme vers le premium), gestion des réseaux sociaux, agents IA, logiciels sur mesure, cartes NFC d''avis Google, fidélité digitale sans appli, borne tactile sans contact, vitrine interactive.'),
  ('mem_formules', 'formules', 'Paiement direct, abonnement mensuel, ou mixte — jamais abusif pour le client.'),
  ('mem_objectif', 'objectif', '3 000 €/mois de rémunération chacun.'),
  ('mem_regles_creation', 'regles_creation', 'Jamais de rendu « template IA », casser les codes UX/UI, animations + 3D, leviers psychologiques de conversion, SEO local poussé, responsive soigné.'),
  ('mem_chaine_production', 'chaine_production', 'Charte → références → Claude Code → GitHub → Vercel → domaine.'),
  ('mem_ton', 'ton', 'Direct, chaleureux, local, professionnel, tutoiement entre nous, vouvoiement des clients.')
insert into public.routines (id, nom, agent_id, mode, heure, intervalle_minutes, plage_debut, plage_fin, jours, jour_du_mois, prompt_tache, actif) values
  ('rt_tri_mails', 'Tri des nouveaux mails', 'lucie', 'intervalle', '08:00', 5, '00:00', '23:59', '{}'::smallint[], null, 'Trie les nouveaux mails de la boîte officielle, résume-les et crée les tâches pour les bons pôles.', true),
  ('rt_sante_sites', 'Santé des sites clients', 'jade', 'intervalle', '08:00', 60, '06:00', '23:00', '{}'::smallint[], null, 'Contrôle les sites clients (HTTP, temps de réponse, certificat SSL, expiration du domaine) et alerte en cas de souci. Sans IA.', true),
  ('rt_boutique', 'Surveillance de la boutique', 'yanis', 'intervalle', '08:00', 120, '08:00', '21:00', '{}'::smallint[], null, 'Nouvelles commandes, commandes en retard d''expédition, stocks bas : alertes dans le Journal. Sans IA.', true),
  ('rt_echues', 'Factures échues → relances', 'remi', 'fixe', '07:15', 15, '08:00', '20:00', '{}'::smallint[], null, 'Repère les factures échues et prépare les relances graduées (J+3, J+10, J+30 à valider).', true),
  ('rt_recap', 'Récap quotidien', 'diane', 'fixe', '07:30', 15, '08:00', '20:00', '{}'::smallint[], null, 'Rédige et envoie le récap quotidien aux destinataires définis dans Réglages, puis archive-le dans le Journal.', false),
  ('rt_standup', 'Stand-up dans La Criée', 'clemence', 'fixe', '08:30', 15, '08:00', '20:00', '{}'::smallint[], null, 'Réunis les responsables de pôle dans La Criée, fais le point et publie le compte-rendu.', false),
  ('rt_leads', '10 leads qualifiés + mails en brouillon', 'hugo', 'fixe', '10:00', 15, '08:00', '20:00', array[1, 2, 3, 4, 5]::smallint[], null, 'Trouve de nouveaux commerces locaux (Google Places), analyse leur site et leur fiche, note-les et propose l''angle d''attaque. Sans IA : les messages sont écrits par Sacha à la demande.', true),
  ('rt_relances_mails', 'Relances des mails sans réponse', 'firmin', 'fixe', '14:00', 15, '08:00', '20:00', '{}'::smallint[], null, 'Repère les mails envoyés restés sans réponse et prépare une relance.', true),
  ('rt_relances_devis', 'Relances des devis en attente', 'margaux', 'fixe', '14:00', 15, '08:00', '20:00', '{}'::smallint[], null, 'Relance les devis en attente de réponse.', true),
  ('rt_point_18h', 'Point de fin de journée', 'diane', 'fixe', '18:00', 15, '08:00', '20:00', '{}'::smallint[], null, 'Fais un point court : ce qui est fait, ce qui attend une validation.', false),
  ('rt_plan_contenu', 'Plan de contenu de la semaine', 'chloe', 'fixe', '08:00', 15, '08:00', '20:00', array[1]::smallint[], null, 'Prépare les publications de la semaine prêtes à poster (Instagram, LinkedIn, TikTok) : 3 posts avec le texte complet, l''idée de visuel et les hashtags, plus une idée de vidéo courte. Joins-les en Markdown.', true),
  ('rt_prospection_auto', 'Prospection automatique', 'sacha', 'fixe', '10:30', 15, '08:00', '20:00', array[1, 2, 3, 4, 5]::smallint[], null, 'Écris aux meilleurs prospects du jour (score, e-mail public) : mails personnalisés envoyés tout seuls, étalés dans la journée, plafond quotidien.', true),
  ('rt_relances_prospects', 'Relance des prospects sans réponse', 'sacha', 'fixe', '15:00', 15, '08:00', '20:00', array[1, 2, 3, 4, 5]::smallint[], null, 'Relance unique, sans IA, des prospects contactés il y a quelques jours et restés sans réponse.', true),
  ('rt_veille_hebdo', 'Veille de la semaine', 'gabin', 'fixe', '09:00', 15, '08:00', '20:00', array[1]::smallint[], null, 'Veille de la semaine pour une agence web de Sète : tendances du web et du référencement local, nouveautés utiles aux commerces, ce que font les agences concurrentes de l''Hérault. 3 recherches au plus, compte rendu court avec les idées actionnables.', true),
  ('rt_article', 'Article de blog de la semaine', 'lina', 'fixe', '09:30', 15, '08:00', '20:00', array[3]::smallint[], null, 'Écris un article de blog prêt à publier pour le site de MJAGENCY (SEO local : Sète, bassin de Thau) sur un sujet utile aux commerçants (avis Google, site vitrine, réseaux sociaux…). Titre, chapô, 4 à 6 intertitres, conclusion avec appel à l''action ; joins le texte en Markdown.', true),
  ('rt_rapport_hebdo', 'Rapport hebdo', 'diane', 'fixe', '17:00', 15, '08:00', '20:00', array[5]::smallint[], null, 'Rédige le rapport hebdo (KPIs, finances avec Héloïse, pipeline, veille avec Gabin).', false),
  ('rt_nuit', 'Nuit au port', 'clemence', 'intervalle', '08:00', 5, '20:00', '08:00', '{}'::smallint[], null, 'Les agents sans tâche rentrent chez eux la nuit ; Lucie et Jade restent de garde. Une tâche réveille l''agent concerné. Aucun crédit utilisé. Désactivée : les agents restent au port jour et nuit.', false),
  ('rt_abonnements', 'Factures des abonnements', 'bastien', 'fixe', '08:00', 15, '08:00', '20:00', '{}'::smallint[], 1, 'Prépare la facture de chaque abonnement actif du mois (envoi après validation en Douane).', true),
  ('rt_fiscal', 'Échéances fiscales', 'agathe', 'fixe', '08:05', 15, '08:00', '20:00', '{}'::smallint[], null, 'Préviens 7 jours avant chaque échéance fiscale et au passage des seuils de TVA.', true),
  ('rt_cloture', 'Clôture du mois', 'heloise', 'fixe', '09:00', 15, '08:00', '20:00', '{}'::smallint[], 1, 'Clôture le mois : CA, encaissements, cotisations estimées (avec Agathe), prévisionnel.', true)
